// Module exposed to the host as "./app" (host loads it as "remote/app").
import { deepMsg } from "./remote-shared";

// remote-internal lazy chunks (loaded only when this exposed module runs)
import("./remote-gadget-a.js").then((m) => console.log("[remote-app] gadget-a:", m.tag()));
import("./remote-gadget-b.js").then((m) => console.log("[remote-app] gadget-b:", m.tag()));

export function render(el) {
  el.textContent = "remote app rendered: " + deepMsg();
}

export default { render };